//! 🏦️ Finite fixture Source ownership, physical stock and original Work persist through Pending.
pub use semio_framework_value_control_contract::*;
pub struct WorkLoan<'a>{remaining:&'a u128,maximum:u64}
impl<'a> WorkLoan<'a>{pub fn new(remaining:&'a u128,maximum:u64)->Self{Self{remaining,maximum}}pub fn original_remaining(&self)->&'a u128{self.remaining}pub fn issued_maximum(&self)->u64{self.maximum}pub fn maximum(&self)->u64{self.maximum.min(u64::try_from(*self.remaining).expect("original fixture work remains within its u64-issued stock"))}}
pub struct Wallet{left:RetainedCloneGrant,work:u128}
impl Wallet{
 pub fn remaining(&self)->RetainedCloneGrant{self.left}
 pub fn original_work(&self)->&u128{&self.work}
 pub fn remaining_work(&self)->u64{u64::try_from(self.work).expect("original fixture work remains within its u64-issued stock")}
 pub fn work_loan(&self,maximum:u64)->WorkLoan<'_>{WorkLoan::new(&self.work,maximum)}
 pub fn from_profile(profile:&serde_json::Value)->Self{Self{left:RetainedCloneGrant{maximum_items:profile["items"].as_u64().unwrap().try_into().unwrap(),maximum_copy_bytes:profile["copyBytes"].as_u64().unwrap().try_into().unwrap(),maximum_capacity_bytes:profile["capacityBytes"].as_u64().unwrap().try_into().unwrap(),maximum_release_bytes:profile["releaseBytes"].as_u64().unwrap().try_into().unwrap(),maximum_depth:profile["depth"].as_u64().unwrap().try_into().unwrap()},work:u128::from(profile["fuel"].as_u64().unwrap())}}
 pub fn loan(&self,items:usize,copy:usize)->RetainedCloneGrant{RetainedCloneGrant{maximum_items:if self.work==0{0}else{self.left.maximum_items.min(items)},maximum_copy_bytes:self.left.maximum_copy_bytes.min(copy),..self.left}}
 pub fn post(&mut self,p:RetainedCloneProgress,work:u128,g:RetainedCloneGrant,heap:(usize,usize)){assert!(p.fits(g));assert!(p.fits(self.left));assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));self.left.maximum_items=self.left.maximum_items.checked_sub(p.copied_items).unwrap();self.left.maximum_copy_bytes=self.left.maximum_copy_bytes.checked_sub(p.copied_bytes).unwrap();self.left.maximum_capacity_bytes=self.left.maximum_capacity_bytes.checked_sub(p.retained_capacity_bytes).unwrap();self.left.maximum_release_bytes=self.left.maximum_release_bytes.checked_sub(p.released_bytes).unwrap();self.work=self.work.checked_sub(work).expect("native fixture depleted its explicit CPU stock");}
}

/// 🏦️ Owns the finite fixture wallet, actual Source dispatch, and original Work authority across turns.
pub struct EffectBank{wallet:Wallet,source:OriginalSourceTurnIssuer,turn:OriginalSourceTurn,work:OriginalWorkAuthority<EffectWorkProducer>,state:OriginalWorkState,action:Option<OriginalWorkActionIdentity>,selected:Option<(RetainedCloneGrant,u64)>,partial:Option<OriginalWorkPartialOutcome>,actual:Option<usize>,marker_pending:bool,admitted:Option<bool>}
struct EffectWorkProducer;
struct EffectWorkContext<'a>{source:&'a OriginalSourceTurnIssuer,turn:&'a OriginalSourceTurn,remaining:&'a u128}
impl OriginalWorkRecipient for EffectWorkProducer{
 type Context<'turn,'source>=EffectWorkContext<'turn> where 'source:'turn;
 fn validate_context<'turn,'source>(&self,c:&Self::Context<'turn,'source>)->Result<(),ValueError> where 'source:'turn{c.source.validate(c.turn).map_err(|_|ValueError::invariant("foreign fixture Source turn"))}
 fn source_turn<'turn,'source>(&self,c:&Self::Context<'turn,'source>)->Option<OriginalSourceTurnIdentity> where 'source:'turn{Some(c.turn.identity())}
 fn admits<'reply,'turn,'source>(&mut self,c:&mut Self::Context<'turn,'source>,quote:OriginalWorkQuote<'reply>,observed:u64,additional:u64)->OriginalWorkQuoteComplete<'reply> where 'source:'turn{quote.complete(Ok(observed.checked_add(additional).is_some_and(|n|u128::from(n)<=*c.remaining)))}
 fn settle_partial<'reply,'turn,'source>(&mut self,c:&mut Self::Context<'turn,'source>,check:OriginalWorkPartialCheck<'reply>)->OriginalWorkPartialCheckComplete<'reply> where 'source:'turn{check.complete(self.validate_context(c))}
 fn recover_partial<'reply,'turn,'source>(&mut self,c:&mut Self::Context<'turn,'source>,check:OriginalWorkPartialCheck<'reply>)->OriginalWorkPartialCheckComplete<'reply> where 'source:'turn{check.complete(self.validate_context(c))}
}
impl EffectBank{
 /// 🆕️ Retains one real fixture Source dispatch and the caller-issued finite wallet.
 pub fn new(wallet:Wallet)->Self{let source=OriginalSourceTurnIssuer::new();let turn=source.issue().expect("fixture Source dispatch");Self{wallet,source,turn,work:OriginalWorkAuthority::new(EffectWorkProducer),state:OriginalWorkState::fresh(),action:None,selected:None,partial:None,actual:None,marker_pending:false,admitted:None}}
 pub fn wallet(&self)->&Wallet{&self.wallet}
 pub fn loan(&self,items:usize,copy:usize)->RetainedCloneGrant{self.wallet.loan(items,copy)}
 /// 🔍️ Observes the original physical marker without moving it from a pending action.
 pub fn actual(&self)->Option<usize>{self.actual}
 /// ⚖️ Takes the actual original Work admission without replacing a child result.
 pub fn take_admitted(&mut self)->Option<bool>{self.admitted.take()}
 /// 🧵️ Runs or resumes the same Source-bound action and claims its exact performed receipt.
 pub fn run<T,E>(&mut self,grant:RetainedCloneGrant,maximum:u64,operation:impl FnOnce(&mut RetainedAllocationEffect<'_>)->RetainedWorkPoll<T,E>)->(RetainedWorkPoll<T,E>,Option<usize>){
  if let Some(selected)=self.selected{assert_eq!(selected,(grant,maximum),"pending fixture action cannot change its original grant or work bound")}else{assert!(!self.marker_pending);assert!(self.admitted.is_none(),"original Work verdict must be inspected");assert!(u128::from(maximum)<=self.wallet.work);self.marker_pending=true;self.selected=Some((grant,maximum));}
  let mut context=EffectWorkContext{source:&self.source,turn:&self.turn,remaining:&self.wallet.work};let actual=&mut self.actual;let action=&mut self.action;let partial=&mut self.partial;let state=self.state.take();
  let (result,performed,state,admitted)=self.work.with_loan(&mut context,|loan|{let mut loan=loan.reborrow();let mut work=OriginalWork{state,recipient:Some(&mut loan)};if action.is_none(){work.begin_turn();assert_eq!(work.prepare_for_action(maximum,action).unwrap(),Some(true))}let mut receipt=None;work.issue_performed_for_action(*action,&mut receipt).unwrap();let before=OriginalWorkSink::observed_work(receipt.as_ref().unwrap());let result=std::panic::catch_unwind(std::panic::AssertUnwindSafe(||{let mut effect=RetainedAllocationEffect::new(grant,maximum,actual,receipt.as_mut().unwrap());operation(&mut effect)}));let performed=OriginalWorkSink::observed_work(receipt.as_ref().unwrap()).checked_sub(before).expect("original receipt regressed");work.claim_performed_for_action(*action,&mut receipt).unwrap();if work.partial_pending_for_action(*action).unwrap(){assert!(work.settle_partial_for_action_into(*action,partial).unwrap());let outcome=partial.take().expect("fixture Source partial reply");assert_eq!(outcome.delta(),performed);assert!(outcome.source_refusal().is_none());}let mut admitted=None;if matches!(&result,Ok(RetainedWorkPoll::Complete(_))){let total=work.performed_total_for_action(*action).unwrap();if total==0&&!work.performed_seen_for_action(*action).unwrap(){work.cancel_for_action(action).unwrap()}else{let mut proof=None;admitted=Some(work.commit_for_action(total,*action,&mut proof).unwrap());work.finish_for_action(&mut proof,action).unwrap()}}(result,performed,work.state,admitted)}).unwrap();self.state=state;self.admitted=admitted;self.wallet.work=self.wallet.work.checked_sub(performed).expect("fixture work stock exhausted");
  match result{Ok(turn)=>{let reported=match &turn{RetainedWorkPoll::Pending{work}=>*work,RetainedWorkPoll::Complete(turn)=>turn.work};assert_eq!(reported,performed,"reported work differs from original performed receipt");if matches!(&turn,RetainedWorkPoll::Complete(_)){assert!(!self.work.has_live_actions());self.selected=None;self.marker_pending=false;(turn,self.actual.take())}else{(turn,None)}},Err(payload)=>std::panic::resume_unwind(payload)}
 }
 /// 🧾️ Posts independently observed physical progress after the action has debited its work.
 pub fn post(&mut self,progress:RetainedCloneProgress,grant:RetainedCloneGrant,heap:(usize,usize)){self.wallet.post(progress,0,grant,heap)}
}

#[cfg(test)]
mod effect_bank_tests{
 use super::*;
 /// 🧪️ A single original pending action keeps its Source, receipt and finite wallet through unwind.
 #[test]fn effect_bank_keeps_original_work_across_unwind(){let fixture:serde_json::Value=serde_json::from_str(include_str!("../🧪️tests/🧫️fixtures/📐️.json")).unwrap();let mut bank=EffectBank::new(Wallet::from_profile(&fixture["stock"]));let work=fixture["work"].as_array().unwrap();let grant=bank.loan(1,8);let first=work[0].as_u64().unwrap();let (turn,actual)=bank.run(grant,5,|effect|{assert!(effect.work_source_turn().is_some());assert!(effect.performed(first).unwrap());RetainedWorkPoll::<(),ValueError>::Pending{work:u128::from(first)}});assert!(matches!(turn,RetainedWorkPoll::Pending{..}));assert_eq!(actual,None);let interrupted=std::panic::catch_unwind(std::panic::AssertUnwindSafe(||bank.run(grant,5,|effect|->RetainedWorkPoll<(),ValueError>{assert!(effect.performed(work[1].as_u64().unwrap()).unwrap());panic!("original fixture producer interrupted")})));assert!(interrupted.is_err());assert_eq!(bank.actual(),None);let last=work[2].as_u64().unwrap();let (turn,actual)=bank.run(grant,5,|effect|{assert!(effect.performed(last).unwrap());RetainedWorkPoll::Complete(RetainedWorkOutcome::<(),ValueError>{result:Ok(()),work:u128::from(last)})});assert!(matches!(turn,RetainedWorkPoll::Complete(RetainedWorkOutcome{result:Ok(()),..})));assert_eq!(actual,None);assert_eq!(bank.take_admitted(),Some(true));assert_eq!(bank.wallet().remaining_work(),0);}
 /// 🔁️ A later action quotes only the finite work still in its original wallet.
 #[test]fn effect_bank_reuses_remaining_stock_without_double_charge(){let fixture:serde_json::Value=serde_json::from_str(include_str!("../🧪️tests/🧫️fixtures/📐️.json")).unwrap();let mut bank=EffectBank::new(Wallet::from_profile(&fixture["stock"]));for units in [2u64,3]{let grant=bank.loan(1,8);let (turn,actual)=bank.run(grant,units,|effect|{assert!(effect.performed(units).unwrap());RetainedWorkPoll::Complete(RetainedWorkOutcome::<(),ValueError>{result:Ok(()),work:u128::from(units)})});assert!(matches!(turn,RetainedWorkPoll::Complete(RetainedWorkOutcome{result:Ok(()),..})));assert_eq!(actual,None);assert_eq!(bank.take_admitted(),Some(true));}assert_eq!(bank.wallet().remaining_work(),0);}

 /// 🔒️ Pending keeps the exact original physical and work authority.
 #[test]fn effect_bank_pending_rejects_changed_original_grant(){let fixture:serde_json::Value=serde_json::from_str(include_str!("../🧪️tests/🧫️fixtures/📐️.json")).unwrap();assert_eq!(fixture["rejectChangedGrant"],true);let mut bank=EffectBank::new(Wallet::from_profile(&fixture["stock"]));let grant=bank.loan(1,8);let (pending,_)=bank.run(grant,2,|effect|{assert!(effect.performed(1).unwrap());RetainedWorkPoll::<(),ValueError>::Pending{work:1}});assert!(matches!(pending,RetainedWorkPoll::Pending{..}));let foreign=RetainedCloneGrant{maximum_items:0,..grant};let attempt=std::panic::catch_unwind(std::panic::AssertUnwindSafe(||bank.run(foreign,2,|_|->RetainedWorkPoll<(),ValueError>{panic!("foreign producer must not run")})));assert!(attempt.is_err());let (completed,_)=bank.run(grant,2,|effect|{assert!(effect.performed(1).unwrap());RetainedWorkPoll::Complete(RetainedWorkOutcome::<(),ValueError>{result:Ok(()),work:1})});assert!(matches!(completed,RetainedWorkPoll::Complete(RetainedWorkOutcome{result:Ok(()),..})));assert_eq!(bank.take_admitted(),Some(true));}

 #[test]fn explicit_zero_work_still_settles_the_original_source_receipt(){let fixture:serde_json::Value=serde_json::from_str(include_str!("../🧪️tests/🧫️fixtures/📐️.json")).unwrap();let mut bank=EffectBank::new(Wallet::from_profile(&fixture["stock"]));let grant=bank.loan(1,8);let (turn,actual)=bank.run(grant,0,|effect|{assert!(effect.performed(0).unwrap());RetainedWorkPoll::Complete(RetainedWorkOutcome::<(),ValueError>{result:Ok(()),work:0})});assert!(matches!(turn,RetainedWorkPoll::Complete(RetainedWorkOutcome{result:Ok(()),..})));assert_eq!(actual,None);assert_eq!(bank.wallet().remaining_work(),fixture["zero"]["remainingWork"].as_u64().unwrap());assert_eq!(bank.take_admitted(),Some(true));let (turn,_)=bank.run(grant,1,|effect|{assert!(effect.performed(1).unwrap());RetainedWorkPoll::Complete(RetainedWorkOutcome::<(),ValueError>{result:Ok(()),work:1})});assert!(matches!(turn,RetainedWorkPoll::Complete(_)));assert_eq!(bank.take_admitted(),Some(true));}

}
